import type { Claim } from '../claims/claims';
import { useTerms } from '../settings/settings';
import { dueBy } from './overdue';

// A claim's due-by: its date plus the sheet's terms.
export function ClaimDueBy({ claim }: { claim: Claim }) {
  const terms = useTerms();
  return <span data-testid="claim-due-by">{dueBy(claim.date, terms)}</span>;
}
import type { Claim } from '../claims/claims';
import { useSheetToday } from '../session/sheetToday';
import { useTerms } from '../settings/settings';
import { overdue } from './overdue';

// Whether a claim is overdue: OPEN (or PENDING), with its due-by before the sheet's today.
export function ClaimOverdue({ claim }: { claim: Claim }) {
  const terms = useTerms();
  const today = useSheetToday();
  return <span data-testid="claim-overdue">{overdue(claim, terms, today) ? 'yes' : 'no'}</span>;
}
import { isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/** A claim's due-by (yyyy-MM-dd): its date plus the terms in days. */
export function dueBy(date: string, terms: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN (or PENDING) and its due-by is before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string): boolean {
  return isOpen(claim) && today !== '' && dueBy(claim.date, terms) < today;
}

/** How many full 30-day periods a claim is overdue on the sheet's today: 0 unless it is overdue. */
export function latePeriods(claim: Claim, terms: number, today: string): number {
  if (!overdue(claim, terms, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim.date, terms)}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimDueBy } from './ClaimDueBy';
import { ClaimOverdue } from './ClaimOverdue';
import { OverdueTotals } from './OverdueTotals';
import { PersonOverdueCount, PersonOverdueTotal } from './PersonOverdue';

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonColumns.fill({ order: 16, Component: PersonOverdueCount }),
  PersonColumnHeads.fill({ order: 17, Component: () => <th>Overdue total</th> }),
  PersonColumns.fill({ order: 17, Component: PersonOverdueTotal }),
  ClaimRowValues.fill({ order: 12, Component: ClaimDueBy }),
  ClaimRowValues.fill({ order: 13, Component: ClaimOverdue }),
  HomeMain.fill({ order: 45, Component: OverdueTotals }),
];
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { personOverdue } from './overdue';

// The sheet's overdue count and overdue-total: everyone's added up.
export function OverdueTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const each = people.map((p) =>
    personOverdue(claims.filter((c) => c.personId === p.id), rates, p.grades, p.held, rules),
  );
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>, totalling{' '}
      <strong data-testid="rollup-overdue-total">{total(each.map((o) => o.total))}</strong>
    </p>
  );
}
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, total } from '../rates/rates';
import type { Rate } from '../rates/rates';
import type { GradeFrom } from '../people/people';
import type { DueRules } from '../settings/settings';
import { overdue } from './dueBy';

export { dueBy, overdue } from './dueBy';

/**
 * A person's overdue claims that count (none of their open ones while they are held): how many, and
 * their dues (late charges included) added up (skipping n/a).
 */
export function personOverdue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  held: boolean,
  rules: DueRules,
): { count: number; total: string } {
  const late = claims.filter((c) => counts(c, held) && overdue(c, rules.terms, rules.today));
  return { count: late.length, total: total(late.map((c) => claimDue(c, rates, grades, rules))) };
}
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import { personOverdue } from './overdue';

function usePersonOverdue(person: Person) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return personOverdue(claims, rates, person.grades, person.held, rules);
}

// How many of a person's counting claims are overdue.
export function PersonOverdueCount({ person }: { person: Person }) {
  return <td data-testid="person-overdue-count">{usePersonOverdue(person).count}</td>;
}

// The dues (late charges included) of a person's overdue counting claims, added up.
export function PersonOverdueTotal({ person }: { person: Person }) {
  return <td data-testid="person-overdue-total">{usePersonOverdue(person).total}</td>;
}
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';

/** A role given to a user name: clerk or steward. A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), and the roles
 * given to user names.
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; policyDate: string; periodNumberingFrom: string; roles: UserRole[] };

/** The floor a sheet starts with: a claim's live due is at least it. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days: a claim is due by its date plus them. */
export const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The roles a user name can be given. */
export const ROLES = ['clerk', 'steward'];

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}

/** The sheet's terms in days: a claim is due by its date plus them. */
export function useTerms(): number {
  return useSettings().data?.terms ?? DEFAULT_TERMS;
}

/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the sheet's floor, terms, late percent and today, its policy
 * date in force (blank: today) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floor: string;
  terms: number;
  latePct: string;
  today: string;
  policyDate: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  const claimDates = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
    [claims],
  );
  return {
    floor: settings?.floor ?? DEFAULT_FLOOR,
    terms: settings?.terms ?? DEFAULT_TERMS,
    latePct: settings?.latePct ?? DEFAULT_LATE_PCT,
    today,
    policyDate: settings?.policyDate || today,
    claimDates,
  };
}
